export async function rejectPayrollWorkflow(t,{userId,instance}){const source=await payrollWorkflowSource(t,{userId,subjectType:instance.subject_type,id:instance.subject_id,forSubmission:false}),actual=await one(t,'SELECT * FROM ty_workflow_instance WHERE id=$1 FOR UPDATE',[instance.id]);if(!actual||actual.status!=='rejected'||!same(actual.last_approver_id,userId)||actual.source_hash!==source.hash||!same(actual.applicant_id,source.original_requester_id)||!await one(t,"SELECT 1 FROM ty_workflow_task WHERE instance_id=$1 AND approver_id=$2 AND status='rejected'",[actual.id,userId]))deny('不是当前操作人的真实驳回回执');await assertPayrollApprovalAccess(t,{userId,subjectType:actual.subject_type,id:actual.subject_id});await t.query('SAVEPOINT payroll_reject');try{if(actual.subject_type==='payroll_source_preview')await t.query("UPDATE ty_pay_preview SET status='cancelled',workflow_instance_id=$2 WHERE id=$1 AND status='draft'",[actual.subject_id,actual.id]);else await cancelBatch(t,{userId,input:{id:source.safe_values.batch_id,expected_revision:source.batch?.revision||Number((await one(t,'SELECT revision FROM ty_pay_batch WHERE id=$1',[source.safe_values.batch_id])).revision),reason:`WORKFLOW REJECTED:${actual.id}`},operationId:`WORKFLOW:${actual.id}:REJECT`,[APPROVAL_RECEIPT]:{...actual,approved_by:userId}});await t.query("UPDATE ty_workflow_instance SET business_state='applied'WHERE id=$1",[actual.id]);await t.query('RELEASE SAVEPOINT payroll_reject');return{domain_rejected:true};}catch(e){await t.query('ROLLBACK TO SAVEPOINT payroll_reject');await t.query('RELEASE SAVEPOINT payroll_reject');await t.query("UPDATE ty_workflow_instance SET business_state='blocked'WHERE id=$1",[actual.id]);await emit(t,source.group_id,`payroll:workflow:${actual.id}:rejection.blocked`,'payroll.rejection.needs_review',{instance_id:actual.id,domain_applied:false});return{domain_rejected:false,blocked:true};}}
async function sourceCandidates(t,u,input){const group=id(input.group_id),cids=input.company_id?await companyDescendants(t,id(input.company_id)):null,lids=input.ledger_id?await ledgerDescendants(t,id(input.ledger_id)):null,rows=[];
 const push=async(row,extraResource=null)=>{const c=await company(t,row.company_id);if(!same(c.group_id,group)||cids&&!cids.includes(String(c.id))||lids&&!lids.includes(String(c.ledger_id))||input.system&&row.system&&row.system!==input.system||input.person_id&&!same(row.person_id,input.person_id)||input.employment_id&&!same(row.employment_id,input.employment_id)||input.domain&&row.domain!==input.domain)return;try{if(extraResource)await access(t,u,extraResource,'read',{...row,group_id:group},[]);const out=await project(t,u,'payroll_sources',{...row,group_id:group},{...row,company_name:c.name,adoption_state:'requires_explicit_preview_and_review'});if(out)rows.push(out);}catch(e){if(!String(e.message).startsWith('E_TY_FORBIDDEN:'))throw e;}};
 const profiles=await q(t,`SELECT DISTINCT ON(c.employment_id,c.system)c.*,p.person_number,p.full_name FROM ty_pay_config c JOIN ty_person p ON p.id=c.person_id WHERE c.group_id=$1 AND c.kind='profile'AND c.status='approved'AND($2::date IS NULL OR c.valid_from<$2::date+interval '1 month'AND(c.valid_to IS NULL OR c.valid_to>$2))ORDER BY c.employment_id,c.system,c.revision DESC,c.id DESC`,[group,input.period?period(input.period):null]);for(const c of profiles)await push({domain:'salary_profile',id:c.id,revision:c.revision,group_id:c.group_id,company_id:c.company_id,person_id:c.person_id,employment_id:c.employment_id,person_number:c.person_number,full_name:c.full_name,system:c.system,currency:c.currency,source_state:'approved',source_amount:null,value_state:'requires_batch_calculation'});
 for(const c of await q(t,`SELECT c.*,p.person_number,p.full_name FROM ty_ps_candidate c LEFT JOIN ty_person p ON p.id=c.person_id WHERE c.group_id=$1 AND c.kind<>'qualification_review'AND c.revision=(SELECT max(x.revision)FROM ty_ps_candidate x WHERE x.group_id=c.group_id AND x.module=c.module AND x.parent_key=c.parent_key AND x.kind=c.kind)ORDER BY c.id`,[group]))await push({domain:'people_candidate',id:c.id,revision:c.revision,group_id:c.group_id,company_id:c.company_id,person_id:c.person_id,employment_id:c.employment_id,person_number:c.person_number,full_name:c.full_name,currency:c.currency,kind:c.kind,source_state:'candidate_not_adopted',source_amount:c.target,value_state:'source_original_amount_requires_channel_and_cost_reconciliation'},c.module==='dormitory'?'people_dorm_payroll':'people_goods_manage');
 for(const c of await q(t,'SELECT o.*,r.group_id,r.person_id,r.id relationship_id FROM ty_leave_lifecycle_cash_obligation o JOIN ty_leave_account a ON a.id=o.account_id JOIN ty_leave_relationship r ON r.id=a.relationship_id WHERE r.group_id=$1 ORDER BY o.id',[group])){const es=await q(t,'SELECT e.*,p.person_number,p.full_name FROM ty_leave_relationship_employment x JOIN ty_employment e ON e.id=x.employment_id JOIN ty_person p ON p.id=e.person_id WHERE x.relationship_id=$1 ORDER BY e.id',[c.relationship_id]);let allowed=!!es.length;for(const e of es){const d=await authorization(t,{userId:u,resource:'payroll_sources',action:'read',groupId:group,companyId:e.company_id,personId:e.person_id,fields:['sources','amount']}),l=await authorization(t,{userId:u,resource:'advanced_leave_payroll',action:'read',groupId:group,companyId:e.company_id,personId:e.person_id,fields:['target','normal_covered']});if(!d.allowed||!l.allowed)allowed=false;}if(!allowed)continue;const selected=es.find(e=>!cids||cids.includes(String(e.company_id)));if(!selected)continue;await push({domain:'leave_cash',id:c.id,revision:c.revision,group_id:group,company_id:selected.company_id,person_id:c.person_id,employment_id:selected.id,employment_options:es.map(e=>({id:e.id,company_id:e.company_id})),person_number:selected.person_number,full_name:selected.full_name,currency:c.currency,source_state:c.status,source_amount:amount(minus({n:BigInt(c.gross_numerator),d:BigInt(c.gross_denominator)},c.normal_covered)),value_state:'confirmed_incremental_entitlement_not_yet_wages'});}
 for(const r of await q(t,`SELECT r.*,c.group_id,c.currency_code,p.person_number,p.full_name FROM ty_perf_result r JOIN ty_perf_cycle c ON c.id=r.cycle_id JOIN ty_person p ON p.id=r.person_id WHERE c.group_id=$1 AND c.status='confirmed'AND r.result_version=c.result_version AND r.kind='person_bonus'AND r.amount IS NOT NULL AND jsonb_array_length(r.issues)=0 AND($2::date IS NULL OR r.period=$2)ORDER BY r.id`,[group,input.period?period(input.period):null])){if((await one(t,"SELECT to_regclass('public.ty_pr_source_alias')IS NOT NULL ok")).ok&&await(await import('./performance-payroll.mjs')).hasNativePerformanceAlias(t,{legacyCycleId:r.cycle_id,employmentId:r.employment_id}))continue;let all=true;for(const c of r.dependencies)if(!(await authorization(t,{userId:u,resource:'payroll_sources',action:'read',groupId:group,companyId:c,personId:r.person_id,fields:['sources','amount']})).allowed)all=false;if(all)await push({domain:'performance_result',id:r.id,revision:r.result_version,group_id:group,company_id:r.company_id,person_id:r.person_id,employment_id:r.employment_id,person_number:r.person_number,full_name:r.full_name,currency:r.currency_code,period:date(r.period).slice(0,7),source_state:'confirmed',source_amount:String(r.amount),value_state:'one_selected_algorithm_requires_parent_reconciliation'},'perf_cycle');}
 const installed=!!(await one(t,"SELECT to_regclass('public.ty_time_report_version')IS NOT NULL ok")).ok;if(installed){const reports=await q(t,"SELECT DISTINCT r.* FROM ty_time_report_version r JOIN ty_time_report_root h ON h.current_report_id=r.id AND h.perspective='employer'WHERE r.group_id=$1 AND r.status='confirmed'AND($2::date IS NULL OR r.period=$2)ORDER BY r.id DESC",[group,input.period?period(input.period):null]);for(const r of reports){const es=await q(t,"SELECT DISTINCT e.*,p.person_number,p.full_name FROM ty_time_report_line l JOIN ty_employment e ON e.id=l.employment_id JOIN ty_person p ON p.id=e.person_id WHERE l.report_id=$1 AND NOT l.receiving_store_only AND EXISTS(SELECT 1 FROM ty_time_report_root h WHERE h.current_report_id=l.report_id AND h.employment_id=l.employment_id AND h.owner_company_id=l.home_company_id AND h.perspective='employer')",[r.id]);for(const e of es)await push({domain:'time_report',id:r.id,revision:r.revision,group_id:group,company_id:e.company_id,person_id:e.person_id,employment_id:e.id,person_number:e.person_number,full_name:e.full_name,period:date(r.period).slice(0,7),grain:r.grain,source_state:'confirmed',source_amount:null,value_state:'typed_minutes_not_money'},'attendance_daily');}}
 const nativeLeavePay=!!(await one(t,"SELECT to_regclass('public.ty_lp_fact')IS NOT NULL ok")).ok;if(nativeLeavePay)for(const r of await(await import('./leave-payroll.mjs')).leavePayCandidates(t,{userId:u,input,helpers:payrollInternals})){if(cids&&!cids.includes(String(r.company_id))||input.system&&r.currency!==SYSTEMS[input.system])continue;rows.push(r);}
 const nativePerformance=!!(await one(t,"SELECT to_regclass('public.ty_pr_award_parent')IS NOT NULL ok")).ok;if(nativePerformance){const adapter=await import('./performance-payroll.mjs');for(const r of await adapter.performanceAwardCandidates(t,{userId:u,input,helpers:payrollInternals})){if(!r.id||!r.company_id||!r.group_id)continue;const c=await company(t,r.company_id);if(!same(c.group_id,group)||cids&&!cids.includes(String(c.id))||lids&&!lids.includes(String(c.ledger_id))||input.system&&r.currency!==SYSTEMS[input.system])continue;rows.push(r);}}
 const nativeLearning=!!(await one(t,"SELECT to_regclass('public.ty_lr_award_parent')IS NOT NULL ok")).ok;if(nativeLearning){const adapter=await import('./learning-payroll.mjs');for(const r of await adapter.learningAwardCandidates(t,{userId:u,input,helpers:payrollInternals})){if(!r.id||!r.company_id||!r.group_id)continue;const c=await company(t,r.company_id);if(!same(c.group_id,group)||cids&&!cids.includes(String(c.id))||lids&&!lids.includes(String(c.ledger_id))||input.system&&r.currency!==SYSTEMS[input.system])continue;rows.push(r);}}const contractInstalled=!!(await one(t,"SELECT to_regclass('public.ty_cp_resolution')IS NOT NULL ok")).ok;if(contractInstalled)for(const r of await(await import('./contract-payroll.mjs')).contractTermCandidates(t,{userId:u,input})){const c=await company(t,r.company_id);if(!same(c.group_id,group)||cids&&!cids.includes(String(c.id))||lids&&!lids.includes(String(c.ledger_id))||input.system&&r.currency!==SYSTEMS[input.system])continue;rows.push(r);}const filtered=search(rows.filter(row=>(!input.domain||row.domain===input.domain)&&(!input.person_id||same(row.person_id,input.person_id))&&(!input.employment_id||same(row.employment_id,input.employment_id))),input.q,['person_number','full_name','company_name','domain','kind']);return{...paging(filtered,input),adapters:{salary_profile:'native',leave_cash:'native',people_candidate:'native',performance_result:'native',performance_award:nativePerformance?'native':'unavailable_not_installed',training_award:nativeLearning?'native':'unavailable_not_installed',time_report:installed?'native':'unavailable_not_installed',contract_terms:contractInstalled?'native':(await one(t,"SELECT to_regclass('public.ty_hr_contract_term')IS NOT NULL ok")).ok?'pending_adapter_not_accepted':'unavailable_not_installed',training_rewards:'unavailable_adapter_not_implemented',workforce_supplier:'native_cost_report_only_not_employee_wages'},source_amount_is_not_payroll_posted_amount:true};}

// Trusted in-process extension seam; never exposed as a broker command.
export const payrollInternals=Object.freeze({access,project,config,approved,company,employment,actualConfig,sourceScope,makeLine,cmd,latest,date,period,monthEnd,hash,numeric,json,timeSource});

export async function personHistory(t,{userId,input}){const person=id(input.person_id),group=id(input.group_id);const rows=await visibleRows(t,userId,{...input,group_id:group,person_id:person},{confirmedOnly:true});for(const row of rows){const costs=await q(t,'SELECT c.* FROM ty_pay_cost_entry c JOIN ty_pay_adoption a ON a.id=c.adoption_id JOIN ty_pay_obligation o ON o.id=a.obligation_id WHERE c.batch_id=$1 AND o.person_id=$2 ORDER BY c.id',[row.batch_id,person]),visible=[];for(const c of costs){const v=await project(t,userId,'payroll_cost',{...c,person_id:person},c);if(v)visible.push(v);}if(visible.length)row.employer_cost_entries=visible;}return{...paging(rows,input),bank_payment_status:'not_instructed_by_payroll_confirmation'};}

async function permits(t,u,res,action,scope,fields){try{await access(t,u,res,action,scope,fields);return true;}catch(e){if(String(e.message).startsWith('E_TY_FORBIDDEN:'))return false;throw e;}}
async function payrollCapabilities(t,u,scope){return{
 can_create_batch:await permits(t,u,'payroll_run','create',scope,['system','currency','period']),
 can_configure:await permits(t,u,'payroll_config','write',scope,['data','evidence_ref']),
 can_set_person_parameters:await permits(t,u,'payroll_sources','write',scope,['data','evidence_ref']),
 can_read_sources:await permits(t,u,'payroll_sources','read',scope,['sources','amount']),
 can_read_cost:await permits(t,u,'payroll_cost','read',scope,['amount']),
};}
export async function workspace(t,args){const input={...args,...(args.input||{})},result=await workspaceData(t,args),scope={group_id:id(input.group_id),company_id:input.company_id?id(input.company_id):undefined},u=args.userId;result.capabilities=await payrollCapabilities(t,u,scope);
 for(const row of result.rows||[]){if(!row.id)continue;const view=input.view||'rows';row.allowed_actions={};
  if(view==='configs'){const raw=await config(t,row.id),res=['relationship','profile','wage_calendar'].includes(raw.kind)?'payroll_confirm':'payroll_config';row.allowed_actions.revise=await permits(t,u,['relationship','profile','wage_calendar'].includes(raw.kind)||raw.person_id?'payroll_sources':'payroll_config','write',raw,['data','evidence_ref']);row.allowed_actions.approve=raw.status==='draft'&&!await sameHuman(t,raw.created_by,u)&&!await humanIsPerson(t,u,raw.group_id,raw.person_id)&&await permits(t,u,res,'approve',raw,['data','status']);}
  if(view==='stat_configs'){const raw=await one(t,'SELECT * FROM ty_pay_stat_config WHERE id=$1',[row.id]),res=raw.person_id?'payroll_confirm':'payroll_config';row.allowed_actions.revise=await permits(t,u,['relationship','profile','wage_calendar'].includes(raw.kind)||raw.person_id?'payroll_sources':'payroll_config','write',raw,['data','evidence_ref']);row.allowed_actions.approve=raw.status==='draft'&&!await sameHuman(t,raw.created_by,u)&&!await humanIsPerson(t,u,raw.group_id,raw.person_id)&&await permits(t,u,res,'approve',raw,['data','status']);}
  if(view==='batches'){const b=await one(t,'SELECT * FROM ty_pay_batch WHERE id=$1',[row.id]),fields=['sources','amount','status'];row.allowed_actions.preview=!['confirmed','cancelled'].includes(b.status)&&await permits(t,u,'payroll_run','write',b,['sources','amount'])&&await permits(t,u,'payroll_sources','write',b,['sources','amount']);row.allowed_actions.cancel=!['confirmed','cancelled'].includes(b.status)&&await permits(t,u,'payroll_run','cancel',b,fields)&&await permits(t,u,'payroll_sources','cancel',b,fields);let confirm=b.status==='reviewed'&&!await sameHuman(t,b.created_by,u)&&await permits(t,u,'payroll_run','write',b,fields)&&await permits(t,u,'payroll_confirm','execute',b,fields)&&await permits(t,u,'payroll_confirm','approve',b,fields);for(const r of await q(t,'SELECT * FROM ty_pay_row WHERE batch_id=$1',[b.id]))if(await humanIsPerson(t,u,r.group_id,r.person_id)||!await permits(t,u,'payroll_confirm','execute',r,fields))confirm=false;row.allowed_actions.confirm=confirm;row.allowed_actions.publish=b.status==='confirmed'&&await permits(t,u,'payroll_confirm','execute',b,['status','items']);if(b.status==='reviewed')row.approval_requirement=await(await import('./platform-workflow.mjs')).approvalRequirement(t,{userId:u,subjectType:'payroll_batch',groupId:b.group_id,companyId:b.company_id,kind:b.system});row.allowed_actions.submit_for_approval=b.status==='reviewed'&&String(b.created_by)===String(u)&&!!row.approval_requirement?.required;}
  if(view==='previews'){const p=await one(t,'SELECT * FROM ty_pay_preview WHERE id=$1',[row.id]),b=await one(t,'SELECT * FROM ty_pay_batch WHERE id=$1',[p.batch_id]);let review=p.status==='draft'&&!await sameHuman(t,p.created_by,u)&&await permits(t,u,'payroll_confirm','approve',b,['sources','amount','status'])&&await permits(t,u,'payroll_run','write',b,['sources','amount']);for(const l of p.planned.lines)if(await humanIsPerson(t,u,b.group_id,l.scope.person_id)||!await permits(t,u,'payroll_confirm','approve',l.scope,['sources','amount','status']))review=false;row.allowed_actions.review=review;row.allowed_actions.adopt=p.status==='reviewed'&&await permits(t,u,'payroll_sources','execute',b,['sources','amount'])&&await permits(t,u,'payroll_run','write',b,['sources','amount']);if(p.status==='draft')row.approval_requirement=await(await import('./platform-workflow.mjs')).approvalRequirement(t,{userId:u,subjectType:'payroll_source_preview',groupId:b.group_id,companyId:b.company_id,kind:b.system});row.allowed_actions.submit_for_approval=p.status==='draft'&&String(p.created_by)===String(u)&&!!row.approval_requirement?.required;}
 }
 return result;
}
